private CubeDesc getTestKylinCubeWithoutSellerLeftJoin() {
  try {
    return getCubeDescManager().getCubeDesc("test_kylin_cube_without_slr_left_join_desc");
  } catch (RuntimeException e) {
    // 处理KYLIN_CONF/KYLIN_HOME未配置的情况
    if (e.getMessage().contains("Didn't find KYLIN_CONF or KYLIN_HOME")) {
      throw new IllegalStateException("Cube description manager initialization failed due to missing configuration", e);
    }
    throw e;
  }
